import numpy as np
from scirel.inference import evaluate_anisotropic_trial
from scirel.diagnostics import reduce_observation_residuals
def solve(payload):
    return {'converged': True, 'failure_reason': None, 'p': payload['params']['p']}
def diagnose(state):
    return {'flux_loops': [state['equilibrium']['p']]}
result = evaluate_anisotropic_trial(params={'p': 3.0}, observations={'flux_loops': {'values': [1.0], 'sigma': [1.0]}}, solver_config={'r_grid': [0.0], 'z_grid': [0.0]}, equilibrium_solver=solve, diagnostic_evaluator=diagnose, residual_reducer=reduce_observation_residuals)
np.testing.assert_allclose(result['residuals'], [2.0])
assert result['chi2'] == 4.0 and result['failure_reason'] is None
